module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

always @(posedge clk) begin
    if (reset) begin
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        case (light)
            2'b00: begin
                light <= 2'b01;
                walk <= 1'b0;
            end
            2'b01: begin
                if (ped) begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end else begin
                    light <= 2'b10;
                    walk <= 1'b0;
                end
            end
            2'b10: begin
                light <= 2'b00;
                walk <= 1'b1;
            end
            default: begin
                light <= 2'b00;
                walk <= 1'b1;
            end
        endcase
    end
end

endmodule

module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

reg [2:0] state;
reg [2:0] next_state;

always @(posedge clk) begin
    if (reset) begin
        state <= 3'd0;
        light <= 2'b00;
        walk <= 1'b1;
    end else begin
        state <= next_state;
        if (state == 3'd0) begin
            light <= 2'b00;
            walk <= 1'b1;
        end else if (state == 3'd1) begin
            light <= 2'b01;
            walk <= 1'b0;
        end else if (state == 3'd2) begin
            light <= 2'b10;
            walk <= 1'b0;
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        next_state <= 3'd0;
    end else begin
        if (state == 3'd0) begin
            if (ped) begin
                next_state <= 3'd2;
            end else begin
                next_state <= 3'd1;
            end
        end else if (state == 3'd1) begin
            next_state <= 3'd2;
        end else if (state == 3'd2) begin
            next_state <= 3'd0;
        end
    end
end

always @(posedge clk) begin
    if (reset) begin
        walk <= 1'b1;
    end else begin
        if (state == 3'd0) begin
            walk <= 1'b1;
        end else begin
            walk <= 1'b0;
        end
    end
end

endmodule

module traffic_light (
    input clk,
    input reset,
    input ped,
    output reg [1:0] light,
    output reg walk
);

    reg [2:0] state;
    reg [2:0] next_state;
    reg [3:0] counter;

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            counter <= 4'd0;
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            if (state == 3'd0) begin
                next_state <= 3'd0;
                counter <= 4'd0;
                light <= 2'b00;
                walk <= 1'b1;
            end else if (state == 3'd1) begin
                if (counter == 3'd2) begin
                    next_state <= 3'd2;
                    counter <= 4'd0;
                end else begin
                    next_state <= 3'd1;
                    counter <= counter + 1;
                end
            end else if (state == 3'd2) begin
                if (counter == 3'd1) begin
                    next_state <= 3'd3;
                    counter <= 4'd0;
                end else begin
                    next_state <= 3'd2;
                    counter <= counter + 1;
                end
            end else if (state == 3'd3) begin
                if (counter == 3'd1) begin
                    next_state <= 3'd0;
                    counter <= 4'd0;
                end else begin
                    next_state <= 3'd3;
                    counter <= counter + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            state <= 3'd0;
            counter <= 4'd0;
        end else begin
            state <= next_state;
            if (state == 3'd0) begin
                counter <= 4'd0;
            end else if (state == 3'd1) begin
                counter <= counter + 1;
            end else if (state == 3'd2) begin
                counter <= counter + 1;
            end else if (state == 3'd3) begin
                counter <= counter + 1;
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            light <= 2'b00;
            walk <= 1'b1;
        end else begin
            if (state == 3'd0) begin
                light <= 2'b00;
                walk <= 1'b1;
            end else if (state == 3'd1) begin
                light <= 2'b01;
                walk <= 1'b0;
            end else if (state == 3'd2) begin
                light <= 2'b10;
                walk <= 1'b0;
            end else if (state == 3'd3) begin
                light <= 2'b00;
                walk <= 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (reset) begin
            walk <= 1'b1;
        end else begin
            if (state == 3'd0) begin
                walk <= 1'b1;
            end else begin
                walk <= 1'b0;
            end
        end
    end

endmodule

